    pumpSub();
    await _teardownAfterRepl(
      runtime.interruptSub,
      runtime.taskSub,
      runtime.inboxTimer,
    );
  }

  /// Aborts the in-flight run, if any (bounded settle happens outside).
  void _abortIfBusy() {
    if (isBusy) {
      _abortRequested = true;
      _agent.abort();
